    if (req.headers.authorization !== "Bearer test-token") return reply(401, { error: "unauthorized" });
    const url = new URL(req.url!, "http://localhost");
    if (req.method === "GET" && url.pathname === "/v1/resources") {
      if (!rateLimited) {
        rateLimited = true;
        res.setHeader("retry-after", "0");
        return reply(429, { error: "rate limited" });
      }
      const cursor = url.searchParams.get("cursor")!;
      cursors.push(cursor);
      const start = cursor === "0" ? 0 : cursor === "next/page+2" ? 20 : -1;
      if (start < 0 || url.searchParams.get("limit") !== "20") return reply(400, { error: "bad pagination" });
      return reply(200, { resources: resources.slice(start, start + 20), next_cursor: start + 20 < resources.length ? "next/page+2" : null });
    }
